import { ProfileScreen } from '@/screens/profile/ProfileScreen'
import { getBlurhashFromUUID } from '@/utils/getBlurhashFromUUID'
import { useMe } from '@/utils/hooks/useMe'
import { useGetOrganizations } from '@/utils/hooks/useGetOrganizations'

export const ProfileContainer = () => {
	const { me } = useMe()
	const { organizations } = useGetOrganizations()

	if (!me || !organizations) {
		return null
	}

	return (
		<ProfileScreen
			displayName={me.displayName}
			email={me.email ?? ''}
			profileImage={me.profile?.photoURL ?? null}
			blurhash={getBlurhashFromUUID(me.id)}
			organizations={organizations?.edges.map(({ node }) => node) ?? []}
		/>
	)
}
